56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    private final ClinicService clinicService;
64	
65	    private final OwnerMapper ownerMapper;
66	
67	    private final PetMapper petMapper;
68	
69	    private final VisitMapper visitMapper;
70	
71	    /**
72	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
73	     * and a domain containing at least one dot, with no whitespace in any segment.
74	     */
75	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
76	
77	    public OwnerRestControllerV1(ClinicService clinicService,
78	                                 OwnerMapper ownerMapper,
79	                                 PetMapper petMapper,
80	                                 VisitMapper visitMapper) {
81	        this.clinicService = clinicService;
82	        this.ownerMapper = ownerMapper;
83	        this.petMapper = petMapper;
84	        this.visitMapper = visitMapper;
85	    }
86	
87	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
88	    @Override
89	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
90	        Collection<Owner> owners;
91	        if (lastName != null) {
92	            owners = this.clinicService.findOwnerByLastName(lastName);
93	        } else {
94	            owners = this.clinicService.findAllOwners();
95	        }
96	        if (owners.isEmpty()) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
105	        Owner owner = this.clinicService.findOwnerById(ownerId);
106	        if (owner == null) {
107	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
108	        }
109	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
110	    }
111	
112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
115	        validateRequiredFields(ownerFieldsDto);
116	        HttpHeaders headers = new HttpHeaders();
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
119	            requireUniqueHousehold(owner.getLastName(), owner.getAddress());
120	        }
121	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
122	        requireUniqueTelephone(telephone);
123	        owner.setTelephone(telephone);
124	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
125	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
126	        this.clinicService.saveOwner(owner);
127	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
128	        headers.setLocation(UriComponentsBuilder.newInstance()
129	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
130	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
131	    }
132	
133	    /**
134	     * Generates the customer code for a newly created owner, formatted {@code '<LAST3>-<NNNN>'}.
135	     * {@code LAST3} is the upper-cased first three letters of the last name and {@code NNNN} is a
136	     * global, 4-digit zero-padded sequence equal to one more than the current number of owners
137	     * (e.g. {@code 'SMI-0007'}).
138	     *
139	     * @param lastName the owner's last name
140	     * @return the generated customer code
141	     */
142	    private String generateCustomerCode(String lastName) {
143	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
144	        int sequence = this.clinicService.findAllOwners().size() + 1;
145	        return String.format("%s-%04d", last3, sequence);
146	    }
147	
148	    /**
149	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
150	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
151	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
152	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
153	     *
154	     * @param ownerFieldsDto the submitted owner fields
155	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
156	     */
157	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
158	        List<String> invalidFields = new ArrayList<>();
159	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
160	            invalidFields.add("firstName");
161	        }
162	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
163	            invalidFields.add("lastName");
164	        }
165	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
166	            invalidFields.add("address");
167	        }
168	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
169	            invalidFields.add("city");
170	        }
171	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
172	            invalidFields.add("telephone");
173	        }
174	        if (!invalidFields.isEmpty()) {
175	            throw new InvalidOwnerFieldsException(invalidFields);
176	        }
177	    }
178	
179	    /**
180	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
181	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
182	     * what gets stored and returned.
183	     *
184	     * @param telephone the raw telephone value from the request
185	     * @return the normalized E.164 telephone number
186	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
187	     */
188	    private String normalizeTelephone(String telephone) {
189	        String e164 = toE164(telephone);
190	        if (e164 == null) {
191	            throw new InvalidOwnerFieldsException(List.of("telephone"));
192	        }
193	        return e164;
194	    }
195	
196	    /**
197	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
198	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
199	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
200	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
201	     * it contains 8 to 15 digits after the {@code '+'}.
202	     *
203	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
204	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
205	     *
206	     * @param telephone the raw telephone value, possibly {@code null}
207	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
208	     */
209	    private String toE164(String telephone) {
210	        if (telephone == null) {
211	            return null;
212	        }
213	        String cleaned = telephone.replaceAll("[ \\-()]", "");
214	        String digits;
215	        if (cleaned.startsWith("+")) {
216	            digits = cleaned.substring(1);
217	        } else {
218	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
219	            digits = "61" + national;
220	        }
221	        if (!digits.matches("[0-9]{8,15}")) {
222	            return null;
223	        }
224	        return "+" + digits;
225	    }
226	
227	    /**
228	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
229	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
230	     * and returned lower-cased.
231	     *
232	     * @param email the raw email value from the request, possibly {@code null}
233	     * @return the lower-cased email, or {@code null} when none was supplied
234	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
235	     */
236	    private String normalizeEmail(String email) {
237	        if (!StringUtils.hasText(email)) {
238	            return null;
239	        }
240	        String trimmed = email.trim();
241	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
242	            throw new InvalidOwnerFieldsException(List.of("email"));
243	        }
244	        return trimmed.toLowerCase(Locale.ROOT);
245	    }
246	
247	    /**
248	     * Rejects a telephone number whose E.164 form is already used by an existing owner. This enforces
249	     * that no two owners share the same E.164 telephone. Existing values are compared by their E.164
250	     * form; a stored value that cannot form a valid E.164 number is compared as-is.
251	     *
252	     * @param telephone the normalized (E.164) telephone of the owner being created
253	     * @throws DuplicateTelephoneException if another owner already has this E.164 telephone
254	     */
255	    private void requireUniqueTelephone(String telephone) {
256	        boolean inUse = this.clinicService.findAllOwners().stream()
257	            .map(Owner::getTelephone)
258	            .filter(existing -> existing != null)
259	            .map(existing -> {
260	                String e164 = toE164(existing);
261	                return e164 != null ? e164 : existing;
262	            })
263	            .anyMatch(telephone::equals);
264	        if (inUse) {
265	            throw new DuplicateTelephoneException(telephone);
266	        }
267	    }
268	
269	    /**
270	     * Rejects an owner whose last name and address match those of an existing owner, where both are
271	     * compared case-insensitively and with runs of whitespace collapsed to a single space (a shared
272	     * household). The caller skips this check when the request opts in via {@code sharesHousehold}.
273	     *
274	     * @param lastName the last name of the owner being created
275	     * @param address the address of the owner being created
276	     * @throws DuplicateHouseholdException if another owner shares the same last name and address
277	     */
278	    private void requireUniqueHousehold(String lastName, String address) {
279	        String normalizedLastName = normalizeForHousehold(lastName);
280	        String normalizedAddress = normalizeForHousehold(address);
281	        boolean inUse = this.clinicService.findAllOwners().stream()
282	            .anyMatch(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
283	                && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress));
284	        if (inUse) {
285	            throw new DuplicateHouseholdException(lastName, address);
286	        }
287	    }
288	
289	    /**
290	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
291	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
292	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
293	     *
294	     * @param value the raw value, possibly {@code null}
295	     * @return the normalized value
296	     */
297	    private String normalizeForHousehold(String value) {
298	        if (value == null) {
299	            return "";
300	        }
301	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
302	    }
303	
304	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
305	    @Override
306	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
307	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
308	        if (currentOwner == null) {
309	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
310	        }
311	        currentOwner.setAddress(ownerFieldsDto.getAddress());
312	        currentOwner.setCity(ownerFieldsDto.getCity());
313	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
314	        currentOwner.setLastName(ownerFieldsDto.getLastName());
315	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
316	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
317	        this.clinicService.saveOwner(currentOwner);
318	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
319	    }
320	
321	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
322	    @Transactional
323	    @Override
324	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
325	        Owner owner = this.clinicService.findOwnerById(ownerId);
326	        if (owner == null) {
327	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
328	        }
329	        this.clinicService.deleteOwner(owner);
330	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
331	    }
332	
333	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
334	    @Override
335	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
336	        Owner owner = this.clinicService.findOwnerById(ownerId);
337	        if (owner == null) {
338	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
339	        }
340	        HttpHeaders headers = new HttpHeaders();
341	        Pet pet = petMapper.toPet(petFieldsDto);
342	        owner.setId(ownerId);
343	        pet.setOwner(owner);
344	        pet.getType().setName(null);
345	        this.clinicService.savePet(pet);
346	        PetDto petDto = petMapper.toPetDto(pet);
347	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
348	            .buildAndExpand(pet.getId()).toUri());
349	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
350	    }
351	
352	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
353	    @Override
354	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
355	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
356	        if (currentOwner != null) {
357	            Pet currentPet = this.clinicService.findPetById(petId);
358	            if (currentPet != null) {
359	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
360	                currentPet.setName(petFieldsDto.getName());
361	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
362	                this.clinicService.savePet(currentPet);
363	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
364	            }
365	        }
366	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
367	    }
368	
369	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
370	    @Override
371	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
372	        HttpHeaders headers = new HttpHeaders();
373	        Visit visit = visitMapper.toVisit(visitFieldsDto);
374	        Pet pet = new Pet();
375	        pet.setId(petId);
376	        visit.setPet(pet);
377	        this.clinicService.saveVisit(visit);
378	        VisitDto visitDto = visitMapper.toVisitDto(visit);
379	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
380	            .buildAndExpand(visit.getId()).toUri());
381	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
382	    }
383	
384	
385	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
386	    @Override
387	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
388	        Owner owner = this.clinicService.findOwnerById(ownerId);
389	        if (owner != null) {
390	            Pet pet = owner.getPet(petId);
391	            if (pet != null) {
392	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
393	            }
394	        }
395	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
396	    }
397	}
